namespace Fanex.Age.UI.TotalBets
{
    public partial class FGLG_Page : TotalBets_Page
    {
        #region Variable
        private string rowBgOdd = Fanex.Age.UI.Common.RowBgOdd;
        private string rowBgEven = Fanex.Age.UI.Common.RowBgEven;
        #endregion

        #region Override
        public override void RenderContent(HtmlTextWriter writer)
        {
            var darkModeName = CurrentUserSession.DarkModeName;
            if (!string.IsNullOrWhiteSpace(darkModeName))
            {
                rowBgOdd = DarkModeColor.RowBgOdd;
                rowBgEven = DarkModeColor.RowBgEven;
            }

            DataTable FGLGList = View as DataTable;

            FGLG_Template tpl = new FGLG_Template();
            tpl.DarkModeName = darkModeName;

            tpl.Contents.LeagueContents.Clear();
            if (FGLGList.Rows.Count > 0)
            {
                tpl.Contents.NotFoundContent.Hide();

                // Render league content
                int currentLeagueId = 0;
                int matchIndex = 0;
                FGLG_Contents_LeagueContents_Block leagueBlock = new FGLG_Contents_LeagueContents_Block();
                FGLG_Contents_LeagueContents_MatchContents_Block matchBlock = new FGLG_Contents_LeagueContents_MatchContents_Block();

                for (int i = 0; i < FGLGList.Rows.Count; i++)
                {
                    DataRow dr = FGLGList.Rows[i];

                    int leagueId = Convert.ToInt32(dr["leagueid"]);

                    if (i == 0 || currentLeagueId != leagueId)
                    {
                        // New league, ignore first row
                        if (i != 0) tpl.Contents.LeagueContents.Append(leagueBlock);

                        matchIndex = 1;
                        currentLeagueId = leagueId;

                        leagueBlock.MatchContents.Clear();
                        leagueBlock.LeagueName = CacheRef.GetLeagueName(leagueId);
                    }
                    else
                    {
                        matchIndex++;
                    }

                    RenderMatchRow(matchBlock, dr, matchIndex, i + 1);

                    leagueBlock.MatchContents.Append(matchBlock);
                }

                if (leagueBlock != null) tpl.Contents.LeagueContents.Append(leagueBlock);
            }

            // Piwik
            if (Sunplus.Agent.Model.BL.Definitions.AppSettings.PiwikEnable)
            {
                tpl.Piwik.PiwikUrl = string.Format(
                    "{0}?idsite={1}",
                    Sunplus.Agent.Model.BL.Definitions.AppSettings.PiwikUrl,
                    Sunplus.Agent.Model.BL.Definitions.AppSettings.PiwikSiteId);
            }
            else
            {
                tpl.Piwik.Clear();
            }

            // Bet List Url
            tpl.BetListsUrl.BetListsUrl = MicroSites.BetListsUrl();

            if (_fullMode)
            {
                writer.Write(tpl);
            }
            else
            {
                writer.Write(tpl.Contents);
            }
        }

        public override object ValidateRequest(System.Collections.Hashtable p)
        {
            if (!CurrentUserSession.SubPageAccess.ViewTotalBets)
            {
                return new ErrorPage_Page(Resources.Lang.strNotAccessPage);
            }

            return null;
        }

        public override object InvokeData(System.Collections.Hashtable p)
        {
            return _TotalBetsBO.GetFGLG();
        }
        #endregion

        #region Utility

        /// <summary>
        /// Render match row
        /// </summary>
        /// <param name="matchBlock"></param>
        /// <param name="dr"></param>
        /// <param name="matchIndex"></param>
        /// <param name="rowIndex"></param>
        private void RenderMatchRow(FGLG_Contents_LeagueContents_MatchContents_Block matchBlock, DataRow dr, int matchIndex, int rowIndex)
        {
            matchBlock.ColorOver = Fanex.Age.UI.Common.RowBgOver;
            matchBlock.ColorClass = (matchIndex % 2) == 0 ? rowBgEven : rowBgOdd;
            matchBlock.NoValue = rowIndex.ToString();
            matchBlock.TimeValue = dr["showtime"].ToString();
            matchBlock.HomeValue = CacheRef.GetTeamName(Convert.ToInt32(dr["homeid"])) + ((bool)dr["isNeutral"] ? Resources.Lang.IsNeutral : string.Empty);
            matchBlock.AwayValue = CacheRef.GetTeamName(Convert.ToInt32(dr["awayid"]));

            RenderFullTimeFGLG(matchBlock, dr);

            RenderHalfTimeFGLG(matchBlock, dr);

            matchBlock.MatchId = dr["matchid"].ToString();
        }

        private void RenderHalfTimeFGLG(FGLG_Contents_LeagueContents_MatchContents_Block matchBlock, DataRow dr)
        {
            if (Convert.ToInt16(dr["betcount_127"]) != 0)
            {
                matchBlock.FirstHomeValue1H = PositiveNumberRoundColor(dr["127_WinLost_HomeFG"]);
                matchBlock.LastHomeValue1H = PositiveNumberRoundColor(dr["127_WinLost_HomeLG"]);
                matchBlock.FirstAwayValue1H = PositiveNumberRoundColor(dr["127_WinLost_AwayFG"]);
                matchBlock.LastAwayValue1H = PositiveNumberRoundColor(dr["127_WinLost_AwayLG"]);
                matchBlock.NoGoalValue1H = PositiveNumberRoundColor(dr["127_WinLost_NoGoal"]);
            }
            else
            {
                matchBlock.FirstHomeValue1H = string.Empty;
                matchBlock.LastHomeValue1H = string.Empty;
                matchBlock.FirstAwayValue1H = string.Empty;
                matchBlock.LastAwayValue1H = string.Empty;
                matchBlock.NoGoalValue1H = string.Empty;
            }
        }

        private void RenderFullTimeFGLG(FGLG_Contents_LeagueContents_MatchContents_Block matchBlock, DataRow dr)
        {
            if (Convert.ToInt16(dr["betcount_14"]) != 0)
            {
                matchBlock.FirstHomeValue = PositiveNumberRoundColor(dr["14_WinLost_HomeFG"]);
                matchBlock.LastHomeValue = PositiveNumberRoundColor(dr["14_WinLost_HomeLG"]);
                matchBlock.FirstAwayValue = PositiveNumberRoundColor(dr["14_WinLost_AwayFG"]);
                matchBlock.LastAwayValue = PositiveNumberRoundColor(dr["14_WinLost_AwayLG"]);
                matchBlock.NoGoalValue = PositiveNumberRoundColor(dr["14_WinLost_NoGoal"]);
            }
            else
            {
                matchBlock.FirstHomeValue = string.Empty;
                matchBlock.LastHomeValue = string.Empty;
                matchBlock.FirstAwayValue = string.Empty;
                matchBlock.LastAwayValue = string.Empty;
                matchBlock.NoGoalValue = string.Empty;
            }
        }
        /// <summary>
        /// Round color for positive number
        /// </summary>
        /// <param name="number"></param>
        /// <returns></returns>
        private string PositiveNumberRoundColor(object number)
        {
            decimal num = Convert.ToDecimal(number);
            return (num > 0) ? "<span class='text-red'>" + Formater.FormatNumber2(num, CurrentUserSession.Language) + "</span>" : Formater.FormatNumber2(num, CurrentUserSession.Language);
        }
        #endregion
    }
}
